"""Add source-backed Spring RestClient transport lessons without inventing remote guarantees."""
from __future__ import annotations
import datetime, html, json, pathlib, re, uuid

ROOT=pathlib.Path(__file__).resolve().parents[1]
FILE=ROOT/'src/data/fixtures.json'
rows=json.loads(FILE.read_text());by={row['path']:row for row in rows}
stamp=datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    value=html.escape(value)
    return '<p>'+re.sub(r'\[\[([^|]+)\|([^\]]+)\]\]',lambda m:'<a href="/'+m[1]+'">'+m[2]+'</a>',value)+'</p>'

lessons=[
 dict(section='spring-web',slug='restclient-explicit-factory',title='Spring RestClient transport: run the factory you configured',opening='An explicit RestClient request factory makes the local network transport a deliberate part of a call contract.',heads=[
  ('The checked local call',['RestClientBoundaryTest builds a client with SimpleClientHttpRequestFactory, a 300ms connect timeout and a one-second read timeout. A loopback server responds to GET /risk/receipt-2048 with approved. The test asserts the returned body, so it checks a real HTTP exchange through the selected factory rather than a stubbed RestClient response.','The same factory is reused in the stalled-response and uncertain-write checks. [[spring/restclient-request-factory|The architecture lesson]] explains why pinning the transport matters: classpath changes can alter an implicit selection. This test checks only the simple JDK-backed factory. It does not compare Apache, Jetty or JDK HttpClient implementations.']),
  ('Scope the evidence',['The server binds 127.0.0.1 on a random port and is stopped after each test. The response is tiny and local. It does not exercise TLS, DNS, connection pooling, proxies, response-body streaming or a remote upstream. The fixture shows how to wire a factory and inspect a real response; it does not establish production throughput.','Do not share a mutable setup object across concurrent requests without testing its thread behavior. Build the client once with the chosen factory and measure the packaged artifact under load. [[spring/restclient-read-deadline|The deadline fixture]] supplies one more bounded transport check.'])],code='var factory = new SimpleClientHttpRequestFactory();\nfactory.setConnectTimeout(Duration.ofMillis(300));\nfactory.setReadTimeout(readTimeout);\nreturn RestClient.builder()\n    .requestFactory(factory)\n    .baseUrl("http://127.0.0.1:" + upstream.getAddress().getPort())\n    .build();',lang='java',proof='RestClientBoundaryTest.explicitFactoryReadsTheUpstreamResponse',limit='One loopback exchange with a simple request factory is checked. No TLS, proxy, pool, remote latency or concurrent load is tested.',mistakes=['Do not infer the request factory from the RestClient call site alone.','Do not call a loopback success test a production latency measurement.','Do not confuse a real local socket with a real external service.'],links=['spring/restclient-request-factory','spring/restclient-read-deadline','spring/restclient-status-no-retry','spring/restclient-timeout-budget']),
 dict(section='spring-web',slug='restclient-status-no-retry',title='Spring RestClient 503 response: count attempts before adding a retry',opening='A 503 response is a remote status, and the checked RestClient call makes one request before surfacing that failure.',heads=[
  ('Count the local exchange',['The loopback server increments a counter and returns 503 for the receipt-risk GET. RestClientBoundaryTest expects HttpServerErrorException from retrieve().body(String.class), then asserts that the server saw one request. This proves there is no implicit second attempt in this configured fixture. It does not prove every interceptor or future client configuration is retry-free.','A retry policy is an application decision. For an idempotent GET, another attempt may be allowed only if the total request deadline has room and the upstream contract permits it. [[spring/restclient-timeout-budget|The budget worksheet]] keeps the attempts inside the public request deadline.']),
  ('Do not flatten all failures',['A 503 means a server sent an HTTP response. [[spring/restclient-read-deadline|The stalled-response case]] is different: it fails while waiting for bytes. Authentication errors, malformed responses and validation failures also need different policies. Retrying every exception can multiply load during an outage.','Record status class, attempt count and elapsed time using bounded labels. Do not put a receipt ID into a metric tag. [[spring/metric-cardinality|The meter lesson]] explains the memory and backend cost of unbounded identities.'])],code='assertThrows(HttpServerErrorException.class, () -> riskClient.get()\n    .uri("/risk/receipt-2048").retrieve().body(String.class));\nassertEquals(1, upstreamRequestCount.get());',lang='java',proof='RestClientBoundaryTest.errorStatusDoesNotTriggerAnImplicitRetry',limit='A local 503 with one explicit request factory is checked. No retry interceptor, production upstream or shared outage is included.',mistakes=['Do not call a 503 a connection timeout.','Do not assume a framework call will retry safely by itself.','Do not add unbounded retries to an overloaded upstream.'],links=['spring/restclient-read-deadline','spring/restclient-timeout-budget','spring/restclient-idempotent-retry','spring/metric-cardinality']),
 dict(section='spring-web',slug='restclient-read-deadline',title='Spring RestClient read timeout: reject a server that accepts but stalls',opening='A read timeout bounds how long this client waits for a response after its connection has reached the loopback server.',heads=[
  ('Hold the response on purpose',['The local server accepts GET /risk/receipt-2048 and waits on a latch instead of sending headers. The client uses an 80ms read timeout. RestClientBoundaryTest expects ResourceAccessException and confirms that the server handler received the request. Only then does it release the handler. A second latch makes the test about response waiting rather than an accidental connection failure.','[[spring/restclient-explicit-factory|The selected SimpleClientHttpRequestFactory]] has separate connect and read timeout settings. The test checks the latter. It does not check DNS resolution, connection-pool acquisition or a response body that trickles bytes without completing.']),
  ('The remote side may still work',['When the client stops waiting, the server-side operation is not automatically cancelled. The handler may later write to a closed socket. For a GET that is usually a wasted computation; for a POST it can be a committed mutation with no received response. [[spring/restclient-uncertain-commit|The write fixture]] makes that ambiguity visible.','A read timeout is not the same as the public endpoint deadline. Add connection wait, serialization, transaction time and any retry delay before choosing a number. The 80ms fixture exists to make the test quick and deterministic; it is not a production recommendation.'])],code='assertThrows(ResourceAccessException.class, () -> client(Duration.ofMillis(80)).get()\n    .uri("/risk/receipt-2048").retrieve().body(String.class));\nassertTrue(requestReceived.await(1, TimeUnit.SECONDS));',lang='java',proof='RestClientBoundaryTest.readTimeoutStopsWaitingForAStalledResponse',limit='Only a local server that delays response headers is checked. Slow streaming, DNS, proxy and TLS behavior remain untested.',mistakes=['Do not treat a read timeout as evidence that the remote operation stopped.','Do not confuse a stalled response with a refused connection.','Do not copy the short test timeout into a production service without measurement.'],links=['spring/restclient-explicit-factory','spring/restclient-uncertain-commit','spring/restclient-timeout-budget','spring/restclient-status-no-retry']),
 dict(section='spring-web',slug='restclient-uncertain-commit',title='Spring HTTP timeout after POST: the write may already exist',opening='A caller can time out after a remote service commits a write but before its response reaches the caller.',heads=[
  ('The checked ordering',['The loopback /remote-reservations handler records an Idempotency-Key and increments a write counter before it waits on a latch. The RestClient POST uses an 80ms read timeout, so the first call throws ResourceAccessException while the server still records one write. The test waits for a server-side commit signal before asserting the counter. That is the important order.','The first response may fail when the server later writes to a socket the client closed. The client exception cannot tell whether the reservation exists. [[spring/restclient-replay-key|The next fixture]] sends the same key again and checks the server-side deduplication rule.']),
  ('Carry uncertainty into the API contract',['A public receipt endpoint should not translate this transport failure into a claim that the remote write rolled back. It may return a retryable error with a stable command identifier, or reconcile the remote state before reporting a final decision. The exact response policy depends on the upstream contract.','The fixture is not a payment provider and has no database. Its in-memory key set intentionally models one server process. A real integration needs durable deduplication, retention rules, tenant scoping and behavior under simultaneous requests or restarts. [[spring/tenant-idempotency-key-scope|The local H2 command fixture]] covers a different, transactional replay boundary.'])],code='String key = exchange.getRequestHeaders().getFirst("Idempotency-Key");\nif (key != null && committedKeys.add(key)) {\n    writes.incrementAndGet();\n    firstWriteCommitted.countDown();\n}',lang='java',proof='RestClientBoundaryTest.aTimedOutWriteMayHaveCommittedBeforeTheCallerRetries',limit='The remote state is an in-memory set in one loopback process. No durable upstream, concurrent duplicate race or network partition is checked.',mistakes=['Do not infer rollback from a client-side timeout.','Do not generate a new command key for the same uncertain write.','Do not treat an in-memory set as durable remote deduplication.'],links=['spring/restclient-replay-key','spring/restclient-idempotent-retry','spring/tenant-idempotency-key-scope','spring/outbox-atomic-write']),
 dict(section='spring-web',slug='restclient-replay-key',title='Spring HTTP replay key: two requests, one modeled reservation',opening='A stable replay key lets a remote handler identify two attempts as one logical command when it enforces that key.',heads=[
  ('Repeat the same command',['After the first timed-out POST, RestClientBoundaryTest releases the delayed response and sends another POST with the same Idempotency-Key. The local server sees two HTTP requests, returns reservation-2048 and records one write. The test checks both counters and the stored key. This is a server-enforced behavior; RestClient does not provide deduplication by itself.','The key belongs to the normalized command and tenant. [[spring/tenant-idempotency-key-scope|The tenant-scoping lesson]] explains why the same opaque text used by a different tenant must not select another tenant’s result. A key reused for changed request contents should be rejected rather than returning the first response.']),
  ('Draw the boundary around the model',['The loopback handler uses a concurrent in-memory set, not a database transaction. It has no TTL, payload hash, failure-after-reservation recovery or protection across two server replicas. The test also sends attempts sequentially; it does not race two first requests against the same key.','A production remote service must store the key and result atomically with the mutation, specify retention, and let a caller retrieve the prior result after an uncertain response. [[spring/restclient-uncertain-commit|The timeout trace]] explains why this is necessary.'])],code='// The second POST reuses tenant-east-receipt-2048.\nassertEquals(2, requests.get());\nassertEquals(1, writes.get());\nassertEquals(Set.of("tenant-east-receipt-2048"), committedKeys);',lang='java',proof='RestClientBoundaryTest.aTimedOutWriteMayHaveCommittedBeforeTheCallerRetries',limit='Sequential local requests and one in-memory remote process are checked. Durable replay, TTL, changed payloads and concurrent first-use races remain open.',mistakes=['Do not call a header a deduplication guarantee unless the server enforces it.','Do not reuse one key for a changed command.','Do not claim a sequential set test proves a distributed race.'],links=['spring/restclient-uncertain-commit','spring/tenant-idempotency-key-scope','spring/idempotent-receipt-post','spring/restclient-idempotent-retry']),
 dict(section='spring-testing',slug='restclient-loopback-test-boundary',title='Test Spring RestClient on a socket without claiming a remote service',opening='A loopback HTTP server checks the configured client transport more directly than a stubbed response but still leaves deployment behavior open.',heads=[
  ('What four tests establish',['RestClientBoundaryTest uses a random 127.0.0.1 port and an explicit SimpleClientHttpRequestFactory. It checks one 200 body, a single request for 503, a read timeout after the server accepts the request, and a write committed by the local handler before the caller times out. The last test replays the same key and checks two requests against one modeled mutation.','These checks run through a real socket. They can catch a missing URI, wrong HTTP method, unexpected status mapping or missing read deadline in this factory. [[spring/mockmvc-standalone-scope|MockMvc]] instead targets a server-side MVC handler without making this outbound network exchange.']),
  ('What the fixture cannot establish',['The handler and client live in one JVM. There is no TLS handshake, DNS, proxy, connection pool, remote provider, packet loss, process crash or database-backed replay table. The 80ms deadline is chosen for a short test and should not be used as a performance benchmark.','Before release, run the packaged artifact with the chosen transport against a dedicated test service that can delay headers, stream partial bodies, close sockets and return status sequences. Test key retention and concurrent first use against the real upstream contract. [[spring/release-process-boundary-tests|The release test plan]] separates these layers.'])],code='mvn -q -Dtest=RestClientBoundaryTest test',lang='bash',proof='RestClientBoundaryTest has four passing loopback tests',limit='No remote infrastructure, alternate request factory or process restart is covered.',mistakes=['Do not call a mock response a transport test.','Do not call a loopback socket a distributed-system test.','Do not infer concurrency safety from sequential key replay.'],links=['spring/restclient-explicit-factory','spring/restclient-read-deadline','spring/restclient-replay-key','spring/release-process-boundary-tests']),
]

titles={path:row['title'] for path,row in by.items()}
titles.update({'spring/'+s['slug']:s['title'] for s in lessons})
for s in lessons:
    path='spring/'+s['slug'];assert path not in by,path
    assert all(target in titles for target in s['links']),path
    hub=next(row for row in rows if row['type']=='subject' and row['subject']==s['section'])
    body=p(s['opening'])
    for heading,paragraphs in s['heads']:
        body+='<h2>'+html.escape(heading)+'</h2>'+''.join(p(item) for item in paragraphs)
    body+='<h2>Checked source</h2><pre><code class="language-'+s['lang']+'">'+html.escape(s['code'],quote=False)+'</code></pre>'
    body+='<h2>Verification boundary</h2>'+p(s['proof']+'.')
    body+='<h2>Costs and limits</h2>'+p(s['limit'])
    body+='<h3>Common Mistakes</h3><ul>'+''.join('<li>'+html.escape(item)+'</li>' for item in s['mistakes'])+'</ul>'
    body+='<h2>Read next</h2>'+p(', '.join('[['+target+'|'+titles[target]+']]' for target in s['links'])+'.')
    row=by['spring/if-match-receipt-write'].copy()
    row.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://aitrove.in/'+path)),type='article',path=path,title=s['title'],summary=s['opening'],body=body,subject=s['section'],difficulty='Intermediate',status='published',tags=['spring','restclient','http'],featured=False,sort_order=1200+len(rows),published_at=stamp,created_at=stamp,updated_at=stamp)
    row['data']={'subject_root':'spring/spring-boot','section_path':hub['path'],'kind':'tutorial','content_format':'html','reading_minutes':max(4,round(len(re.sub(r'<[^>]+>',' ',body).split())/150)),'author_path':'authors/aitrove-editorial','seo_ready':True,'related':[{'path':target,'title':titles[target]} for target in s['links']],'framework_version':'Spring Boot 4.0.8 / Spring Framework 7','java_version':'21 source-kit baseline','verification_suite':s['proof'],'download_path':'/downloads/aitrove-spring-source-kit.zip'}
    rows.append(row);by[path]=row

groups={'spring-web':('Checked RestClient calls',[s['slug'] for s in lessons if s['section']=='spring-web']), 'spring-testing':('Outbound HTTP verification',['restclient-loopback-test-boundary'])}
for section,(title,slugs) in groups.items():
    hub=next(row for row in rows if row['type']=='subject' and row['subject']==section)
    paths=['spring/'+slug for slug in slugs]
    hub['data']['modules'].append({'title':title,'summary':'Read the checked transport, timeout and replay contracts.','lessons':paths});hub['updated_at']=stamp
    if '<h2>Section lessons</h2>' in hub['body']:
        links='<ul>'+''.join('<li><a href="/'+path+'">'+html.escape(titles[path])+'</a></li>' for module in hub['data']['modules'] for path in module['lessons'])+'</ul>'
        hub['body']=re.sub(r'(<h2>Section lessons</h2>)[\s\S]*?(<h2>Continue learning</h2>)',lambda m:m[1]+links+m[2],hub['body'])

# Correct prior design-only statements now that the local transport fixture exists.
revisions={
 'spring/restclient-request-factory':[
  ('The current source kit has no RestClient network fixture. The configuration below is a design sketch, not a compiled or load-tested example.','RestClientBoundaryTest now runs an explicit SimpleClientHttpRequestFactory against a loopback HTTP server. The configuration below remains a design sketch; the checked test uses a concrete factory and a random local port.'),
  ('No RestClient request-factory test exists in the source kit; the code is a configuration sketch.','RestClientBoundaryTest.explicitFactoryReadsTheUpstreamResponse checks a selected SimpleClientHttpRequestFactory over loopback; the displayed generic factory variable is a design sketch.')],
 'spring/restclient-timeout-budget':[
  ('The current kit checks local H2 transaction behavior and a fake transport retry, not a real HTTP client under latency. The snippet is a budget worksheet; no configured request-factory timeout is claimed as tested here.','The kit now checks an 80ms read timeout against a loopback server that accepts the request and stalls. The snippet remains a budget worksheet; it does not establish a 900ms end-to-end service deadline.'),
  ('No live RestClient timeout test exists; OutboxRelayFlowTest checks a separate fake-transport retry boundary.','RestClientBoundaryTest.readTimeoutStopsWaitingForAStalledResponse checks a local HTTP read timeout. OutboxRelayFlowTest covers a separate fake-transport retry boundary.')],
 'spring/restclient-idempotent-retry':[
  ('The current source kit does not call a real downstream HTTP service, so this article defines the release contract to test, not a tested client implementation.','The source kit now calls a local HTTP handler over loopback. It shows a write before timeout and a same-key replay against an in-memory deduplicating server; it still does not call a real downstream provider or prove durable deduplication.'),
  ('Local receipt and tenant replay fixtures are checked; no external HTTP retry is executed.','RestClientBoundaryTest.aTimedOutWriteMayHaveCommittedBeforeTheCallerRetries checks a sequential loopback replay; no external provider or distributed retry is tested.')],
 'spring/release-process-boundary-tests':[
  ('The missing matrix still includes a target database, two application versions running together, a real broker, process kill between consumer commit and acknowledgement, and the actual proxy.','The source kit now also checks a loopback RestClient read timeout and uncertain write. The missing matrix still includes a target database, two application versions running together, a real broker, process kill between consumer commit and acknowledgement, and the actual proxy.')],
}
for path,replacements in revisions.items():
    row=by[path]
    for before,after in replacements:
        assert before in row['body'],(path,before)
        row['body']=row['body'].replace(before,after)
    row['updated_at']=stamp
by['spring/restclient-idempotent-retry']['body']=by['spring/restclient-idempotent-retry']['body'].replace('No remote service, transport-level failure injection or cross-system reconciliation test is present.','No production remote service, distributed failure injection or cross-system reconciliation test is present.')

reverse={
 'spring/restclient-request-factory':['spring/restclient-explicit-factory'],
 'spring/restclient-timeout-budget':['spring/restclient-read-deadline'],
 'spring/restclient-idempotent-retry':['spring/restclient-uncertain-commit','spring/restclient-replay-key'],
 'spring/tenant-idempotency-key-scope':['spring/restclient-replay-key'],
 'spring/testing-boundaries':['spring/restclient-loopback-test-boundary'],
 'java/versioned-migrations':['spring/restclient-uncertain-commit'],
}
for path,targets in reverse.items():
    row=by[path];marker='<h2>Checked outbound HTTP continuation</h2>'
    row['body']=row['body'].split(marker)[0]+marker+p('Continue with '+', '.join('[['+target+'|'+titles[target]+']]' for target in targets)+'.');row['updated_at']=stamp

quiz_path='quizzes/spring-restclient-boundaries';assert quiz_path not in by
questions=[
 ('Which request factory is explicit in the loopback tests?',['SimpleClientHttpRequestFactory','An unspecified implicit factory','A remote proxy factory'],0,'The test constructs the simple factory and passes it to RestClient.builder().'),
 ('What does the 200 response test inspect?',['The body returned through a real loopback socket','Only a mocked method call','A production risk service'],0,'The local server sends approved and the client reads it.'),
 ('A 503 arrives in the checked fixture. How many requests does the server count?',['One','Two','An unbounded retry loop'],0,'No retry is configured in that fixture.'),
 ('What exception family represents the 503 from retrieve()?',['HttpServerErrorException','ResourceAccessException','OptimisticLockingFailureException'],0,'The server returned an HTTP error status.'),
 ('Which event occurs before the read-timeout assertion?',['The server handler receives the request','A database row is rolled back','A proxy drains traffic'],0,'A latch confirms the server accepted the call.'),
 ('What does the 80ms read timeout establish?',['The caller stops waiting for the stalled response','The remote operation is cancelled','A 900ms public deadline is satisfied'],0,'The local handler may keep working after the client leaves.'),
 ('Can a timed-out POST already have changed the remote state?',['Yes','No','Only if it returned 200'],0,'The handler records a write before holding its response.'),
 ('Who enforces the replay key in the local test?',['The loopback handler','RestClient itself','The HTTP method name'],0,'The handler stores keys in a concurrent set.'),
 ('How many requests and modeled writes follow the same-key retry?',['Two requests and one write','One request and two writes','Two requests and two writes'],0,'The same key selects the prior modeled result.'),
 ('Does the in-memory key set prove durable remote deduplication?',['No','Yes','Only for TLS'],0,'A restart or a second server instance is not checked.'),
 ('What must be tested separately for a production client?',['The chosen transport with real TLS, proxy and upstream failures','Only the article title','The local JVM name'],0,'Loopback covers a narrow transport path.'),
 ('Which boundary does the RestClient fixture leave open?',['Concurrent first use of one key across replicas','One local 503','A local stalled response'],0,'The key replay is sequential in one process.'),
]
quiz=by['quizzes/spring-boot-startup'].copy()
quiz.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://aitrove.in/'+quiz_path)),path=quiz_path,title='Spring RestClient transport and replay quiz',summary='Twelve explained questions on status, timeout and uncertain remote writes.',sort_order=1200,published_at=stamp,created_at=stamp,updated_at=stamp)
quiz['body']=p('A self-check on the four local RestClient transport fixtures and their limits.')+'<h2>Review before answering</h2><ul>'+''.join('<li><a href="/'+path+'">'+html.escape(titles[path])+'</a></li>' for path in ['spring/restclient-explicit-factory','spring/restclient-status-no-retry','spring/restclient-read-deadline','spring/restclient-uncertain-commit','spring/restclient-replay-key'])+'</ul><h3>Common Mistakes</h3><ul><li>Do not infer rollback from timeout.</li><li>Do not assign deduplication to the client.</li><li>Do not call one loopback process a distributed integration test.</li></ul>'
quiz['data']={'questions':[{'prompt':prompt,'options':options,'answer':answer,'explanation':explanation} for prompt,options,answer,explanation in questions],'duration_minutes':12,'subject_root':'spring/spring-boot','section_path':'spring/quizzes','content_format':'html','seo_ready':True}
rows.append(quiz)
hub=by['spring/quizzes'];hub['data']['modules'].append({'title':'Outbound HTTP','summary':'Twelve checks on local status, timeout and replay.','lessons':[quiz_path]});hub['updated_at']=stamp
if '<h2>Section lessons</h2>' in hub['body']:
    all_titles={**titles,quiz_path:quiz['title']}
    links='<ul>'+''.join('<li><a href="/'+path+'">'+html.escape(all_titles[path])+'</a></li>' for module in hub['data']['modules'] for path in module['lessons'])+'</ul>'
    hub['body']=re.sub(r'(<h2>Section lessons</h2>)[\s\S]*?(<h2>Continue learning</h2>)',lambda m:m[1]+links+m[2],hub['body'])

FILE.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'articles':len(lessons),'quizQuestions':len(questions),'paths':['spring/'+s['slug'] for s in lessons]}))
